import{_ as a,o as t,c as s,ao as o}from"./chunks/framework.C5x47wXO.js";const u=JSON.parse('{"title":"Release process","description":"","frontmatter":{},"headers":[],"relativePath":"developer/release-process.md","filePath":"developer/release-process.md","lastUpdated":null}'),r={name:"developer/release-process.md"};function l(i,e,n,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="Release-process" tabindex="-1">Release process <a class="header-anchor" href="#Release-process" aria-label="Permalink to &quot;Release process {#Release-process}&quot;">​</a></h1><p>EpiBranch and its two satellite packages, EpiNetwork and EpiHouseholds under <code>lib/</code>, are released from <code>main</code> through the General registry. EpiBranch goes first, because the satellites depend on it.</p><h2 id="Releasing-EpiBranch" tabindex="-1">Releasing EpiBranch <a class="header-anchor" href="#Releasing-EpiBranch" aria-label="Permalink to &quot;Releasing EpiBranch {#Releasing-EpiBranch}&quot;">​</a></h2><ol><li><p>Open a release pull request that sets <code>version</code> in <code>Project.toml</code> and folds the changelog fragments into <code>CHANGELOG.md</code> with <code>task changelog-release -- X.Y.Z</code>. This deletes the fragments; apply the <code>no changelog</code> label to the pull request.</p></li><li><p>Merge it. Comment <code>/register</code> on any issue or pull request, or run the Register workflow from the Actions tab. The workflow posts <code>@JuliaRegistrator register</code> on the head of <code>main</code>. JuliaRegistrator opens the registry pull request. Once it merges, TagBot creates the GitHub release.</p></li></ol><h2 id="Releasing-a-satellite" tabindex="-1">Releasing a satellite <a class="header-anchor" href="#Releasing-a-satellite" aria-label="Permalink to &quot;Releasing a satellite {#Releasing-a-satellite}&quot;">​</a></h2><p>Each satellite has its own <code>Project.toml</code>, with its own version and a compat bound on EpiBranch; bump those in the release pull request. Once the EpiBranch version it needs is in the registry, comment <code>/register lib/EpiNetwork</code> or <code>/register lib/EpiHouseholds</code>, and the workflow adds the <code>subdir=</code> the Registrator needs. Register each satellite separately. TagBot has a step per satellite and tags them as <code>EpiNetwork-vX.Y.Z</code> and <code>EpiHouseholds-vX.Y.Z</code> once their registry pull requests merge.</p><h2 id="Release-notes" tabindex="-1">Release notes <a class="header-anchor" href="#Release-notes" aria-label="Permalink to &quot;Release notes {#Release-notes}&quot;">​</a></h2><p><code>CHANGELOG.md</code> holds the folded entries. The GitHub release that TagBot creates has a diff link to the previous tag, the merged pull requests and closed issues since it, and any release notes written under the <code>@JuliaRegistrator register</code> comment.</p>',8)])])}const g=a(r,[["render",l]]);export{u as __pageData,g as default};
